  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly or implicitly takes personal responsibility for a positive outcome, action, or achievement, often by highlighting their direct involvement, advocacy, or role in securing funding, passing legislation, or addressing a specific issue.",
    "clarification": "Credit-claiming is identified when the senator uses language that directly or indirectly attributes a successful outcome, funding, or legislative action to their personal efforts. This includes statements such as 'I secured,' 'I authored,' 'I fought for,' or 'I announced,' as well as references to their committee membership or leadership roles that facilitated the outcome. The focus is on the senator's active role in bringing about a tangible or intangible benefit for their constituents, state, or the nation.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states that he authored legislation creating the National Center designation for Bismarck State College and that he will present the designation formally. This directly attributes the outcome to his personal efforts."
      },
      {
        "document_id": "3482",
        "explanation": "Sens. Mikulski and Cardin announce federal funding for firefighters and explicitly state that Sen. Mikulski is on the committee that funds the program and fights to increase its funding. This highlights their direct involvement in securing the funds."
      },
      {
        "document_id": "4585",
        "explanation": "Senator Schumer explicitly states that he announced federal fire grants for Westchester County and that he has pushed for additional funding for the Assistance to Firefighters Grant Program. This clearly attributes the outcome to his advocacy."
      }
    ],
    "negative_clarification": "Credit-claiming does NOT occur when the senator merely discusses an issue, criticizes a policy, or expresses an opinion without attributing a specific positive outcome or action to their personal efforts. Statements that are purely informational, analytical, or critical—without linking the senator to a tangible achievement—do not qualify as credit-claiming. Additionally, general statements of support or concern, without explicit or implicit claims of personal responsibility, are not considered credit-claiming.",
    "negative_examples": [
      {
        "document_id": "50",
        "explanation": "Senator Reid criticizes the administration's position on global warming but does not claim any personal credit for actions or outcomes. The statement is purely critical and does not attribute any positive result to his efforts."
      },
